"""Six original Hodgkin questions appended to the lymphoid chapter."""
from create_cll import rows,q,AL,CL,EH,NC
from qbank_authoring import ref
HL=ref('NCI: Hodgkin Lymphoma Treatment—Health Professional PDQ','https://www.cancer.gov/types/lymphoma/hp/adult-hodgkin-treatment-pdq')
NV=ref('S1826: Nivolumab-AVD in Advanced Classical Hodgkin Lymphoma','https://www.nejm.org/doi/abs/10.1056/NEJMoa2405888')
q('A node contains characteristic large Hodgkin/Reed-Sternberg cells in an inflammatory background, with CD30, usually CD15 and weak PAX5. Which diagnosis is most likely?', 'Classical Hodgkin lymphoma',[
 ('CLL/SLL','That has a mature small-B-cell pattern rather than the stated classical Hodgkin phenotype.'),('Mantle cell lymphoma','Cyclin D1/SOX11 and a different morphology would be expected.'),('T-lymphoblastic lymphoma','It is a precursor T-cell disease and does not fit the phenotype.')],
 'Interpret the malignant cells within the tissue architecture', '**Classical Hodgkin cells are usually a minority within an inflammatory background.**',['CD30 is not unique to Hodgkin lymphoma.','The complete morphology and marker pattern exclude mimics.'], '**Obtain adequate diagnostic tissue.**',['Architecture and immunophenotyping are important.','Staging and treatment follow a specific Hodgkin pathway.'],[['Tumor cells','Hodgkin/Reed-Sternberg morphology'],['Typical markers','CD30, often CD15, weak PAX5'],['Context','Inflammatory background and architecture']],[HL],style='clinical_scenario')
q('Which symptom qualifies as a conventional lymphoma B symptom?', 'Unexplained weight loss greater than 10% over six months',[
 ('Localized itching alone','Pruritus can be important but is not one of the conventional B criteria.'),('Transient fatigue after a sleepless night','This does not meet a B-symptom definition.'),('A painless node without systemic symptoms','Nodal enlargement alone is not a B symptom.')],
 'Use defined systemic criteria rather than any constitutional complaint', '**B symptoms include significant unexplained weight loss, unexplained fever and drenching night sweats.**',['Evaluate infection and other causes.','Record the symptom duration and severity.'], '**Use symptoms within staging and risk assessment.**',['They do not identify a unique lymphoma histology.','A symptom change during follow-up requires reassessment.'],[['Weight','>10% in 6 months'],['Other criteria','Unexplained fever and drenching sweats'],['Interpretation','Clinical attribution matters']],[HL])
q('Lymphoma involves nodal regions both above and below the diaphragm without a stated diffuse extranodal site. Which Ann Arbor/Lugano anatomical stage is suggested?', 'Stage III',[
 ('Stage I','This is localized to one nodal region or a specified single site.'),('Stage II','Multiple nodal regions remain on the same side of the diaphragm.'),('Stage IV solely because two nodal regions are involved','Diffuse extranodal dissemination, not this distribution alone, defines the higher category.')],
 'The diaphragm separates the stage II and III nodal patterns', '**Nodes on both sides support stage III.**',['Complete imaging and clinical assessment are still needed.','A bulky designation and systemic symptoms provide additional information.'], '**Do not confuse stage with biological grade.**',['An advanced-stage lymphoma can still be highly curable.','Treatment also depends on histology, fitness and protocol risk.'],[['I','Single nodal region'],['II','Same side of diaphragm'],['III','Both sides of diaphragm']],[HL])
q('What is the purpose of PET-adapted treatment in an appropriate Hodgkin protocol?', 'Use early metabolic response to adjust treatment intensity according to validated evidence',[
 ('Stop all therapy after any decrease in node size','Morphological shrinkage alone is not the full protocol decision.'),('Treat every residual mass as viable lymphoma without metabolic or tissue assessment','Fibrotic residual masses can persist.'),('Apply an interim-PET rule from one regimen automatically to every other regimen','The evidence is protocol-specific.')],
 'Response-guided therapy seeks disease control with less avoidable toxicity', '**A validated PET scale and the treatment context matter.**',['Deauville assessment compares uptake with reference tissues.','Inflammation can cause false-positive uptake.'], '**Apply the tested adaptation rather than inventing one.**',['Some protocols reduce exposure after a favorable early response.','Persistent suspicious uptake may require further assessment before salvage therapy.'],[['Tool','FDG-PET response'],['Goal','Risk-adapted intensity'],['Limit','Protocol-specific and not perfectly specific']],[HL])
q('Which conclusion is supported by S1826 for advanced classical Hodgkin lymphoma?', 'Nivolumab plus AVD improved progression-free survival compared with brentuximab vedotin plus AVD in the studied population',[
 ('Nivolumab alone was shown to replace all initial chemotherapy','The trial tested a combination with AVD.'),('The trial establishes the identical regimen for every early-stage patient','It studied advanced-stage disease.'),('AVD contains bleomycin','AVD omits bleomycin.')],
 'Match the trial conclusion to the regimen and population', '**S1826 compared N-AVD with BV-AVD in advanced classical Hodgkin lymphoma.**',['The result supports a modern frontline option.','Local approval, fitness and immune-related risks affect implementation.'], '**Keep regimen names precise.**',['AVD is doxorubicin, vinblastine and dacarbazine.','A checkpoint inhibitor has different toxicities from a CD30-directed antibody-drug conjugate.'],[['N-AVD','Nivolumab plus AVD'],['BV-AVD','Brentuximab vedotin plus AVD'],['Trial outcome','Better PFS with N-AVD']],[NV,HL])
q('A patient previously treated for Hodgkin lymphoma develops new exertional dyspnea. Which survivorship principle is most appropriate?', 'Assess treatment-related cardiac and pulmonary toxicity as well as recurrent disease and other causes',[
 ('Assume cure eliminates all later treatment risks','Late effects can emerge after disease control.'),('Diagnose relapse solely from breathlessness','The symptom is nonspecific.'),('Ignore prior anthracycline, bleomycin or radiation exposure','These exposures can guide the differential.')],
 'Long-term outcomes include late toxicity and second-malignancy risk', '**Prior regimen and radiation fields shape follow-up needs.**',['Anthracyclines can affect cardiac function.','Bleomycin or thoracic radiation can affect the lungs.'], '**Use symptom-directed and risk-based surveillance.**',['Address cardiovascular risk factors and relevant screening.','Avoid unnecessary repeated imaging without a clinical or protocol indication.'],[['History','Drug doses and radiation fields'],['New symptom','Broad cause assessment'],['Follow-up','Risk-based survivorship care']],[HL],style='clinical_scenario')
